/// Fetch balance_sheet data into a CSV (incremental or period-enumerated).
pub async fn run(
    years: Option<&[i32]>,
    periods: &str,
    page_size: usize,
    incremental: bool,
) -> Result<PathBuf> {
    run_financial(&CFG, years, periods, page_size, incremental).await
}

/// Import the fetched CSV into Dolt `fin_balance_sheet` (merge/upsert).
pub async fn import_to_dolt(csv_path: Option<&Path>) -> Result<u64> {
    import_financial(&CFG, csv_path).await
}
